import { GlassView, GlassViewProps } from 'expo-glass-effect'
import { colors, useTheme } from '@/theme'
import { Platform, StyleProp, View, ViewStyle } from 'react-native'

const CAN_DO_LIQUID_GLASS =
	Platform.OS === 'ios' && Number.parseFloat(Platform.Version) >= 26.0

export const LiquidGlassView = ({
	children,
	style,
	disabled,
	...props
}: {
	children: React.ReactNode
	disabled?: boolean
	style?: StyleProp<ViewStyle>
} & GlassViewProps) => {
	const { theme } = useTheme()

	if (disabled) {
		return <View style={style}>{children}</View>
	}

	return (
		<GlassView
			style={[
				!CAN_DO_LIQUID_GLASS && { backgroundColor: colors[theme].gray[50] },
				style
			]}
			{...props}
		>
			{children}
		</GlassView>
	)
}
